from __future__ import annotations

import socket
from urllib.parse import urljoin, urlsplit

import requests
from flask import Flask, jsonify, request

MAX_HOPS = 3


class Blocked(Exception):
    pass


def create_app(settings: dict | None = None) -> Flask:
    config = {"allowed_hosts": {"127.0.0.1"}, "allowed_addrs": {"127.0.0.1"}, **(settings or {})}
    app = Flask(__name__)

    def resolve_allowed(url: str) -> tuple[str, str]:
        parts = urlsplit(url)
        if parts.scheme != "http" or parts.hostname not in config["allowed_hosts"]:
            raise Blocked("host not allowed")
        port = parts.port or 80
        addr = socket.getaddrinfo(parts.hostname, port, type=socket.SOCK_STREAM)[0][4][0]
        if addr not in config["allowed_addrs"]:
            raise Blocked("address not allowed")
        return parts.netloc, parts._replace(netloc=f"{addr}:{port}").geturl()

    def fetch(url: str) -> requests.Response:
        for _ in range(MAX_HOPS + 1):
            host_header, pinned = resolve_allowed(url)
            upstream = requests.get(pinned, headers={"Host": host_header}, allow_redirects=False, timeout=3)
            if not upstream.is_redirect:
                return upstream
            url = urljoin(url, upstream.headers["Location"])
        raise Blocked("too many redirects")

    @app.get("/preview")
    def preview():
        try:
            upstream = fetch(request.args.get("url", ""))
        except Blocked as exc:
            return jsonify(error=str(exc)), 403
        except requests.RequestException:
            return jsonify(error="fetch failed"), 502
        return jsonify(status=upstream.status_code, excerpt=upstream.text[:300])

    return app

from __future__ import annotations

import sqlite3

from flask import Flask, jsonify, request


def create_app(settings: dict) -> Flask:
    app = Flask(__name__)

    @app.get("/api/products")
    def products():
        sort = request.args.get("sort", "name")
        direction = "DESC" if request.args.get("order") == "desc" else "ASC"
        needle = f"%{request.args.get('q', '')}%"
        query = f"SELECT id, name, price FROM products WHERE name LIKE ? ORDER BY {sort} {direction}"
        with sqlite3.connect(settings["db_path"]) as conn:
            try:
                rows = conn.execute(query, (needle,)).fetchall()
            except sqlite3.Error:
                return jsonify(error="bad query"), 400
        return jsonify([{"id": i, "name": n, "price": p} for i, n, p in rows])

    return app

from __future__ import annotations

import sqlite3

from flask import Flask, jsonify, request

SORT_COLUMNS = {"id": "id", "name": "name", "price": "price"}


def create_app(settings: dict) -> Flask:
    app = Flask(__name__)

    @app.get("/api/products")
    def products():
        column = SORT_COLUMNS.get(request.args.get("sort", "name"))
        if column is None:
            return jsonify(error="unsupported sort column"), 400
        direction = "DESC" if request.args.get("order") == "desc" else "ASC"
        needle = f"%{request.args.get('q', '')}%"
        query = f"SELECT id, name, price FROM products WHERE name LIKE ? ORDER BY {column} {direction}"
        with sqlite3.connect(settings["db_path"]) as conn:
            rows = conn.execute(query, (needle,)).fetchall()
        return jsonify([{"id": i, "name": n, "price": p} for i, n, p in rows])

    return app

from __future__ import annotations

import secrets

from flask import Flask, jsonify, request


def create_app(settings: dict) -> Flask:
    app = Flask(__name__)
    invoices = {item["id"]: item for item in settings["invoices"]}
    sessions: dict[str, str] = {}

    def current_user() -> str | None:
        return sessions.get(request.headers.get("Authorization", "").removeprefix("Bearer "))

    @app.post("/api/login")
    def login():
        body = request.get_json(silent=True) or {}
        if settings["users"].get(body.get("user")) != body.get("password"):
            return jsonify(error="bad credentials"), 401
        token = secrets.token_hex(16)
        sessions[token] = body["user"]
        return jsonify(token=token)

    @app.get("/api/invoices")
    def list_invoices():
        user = current_user()
        if user is None:
            return jsonify(error="login required"), 401
        return jsonify([i for i in invoices.values() if i["owner"] == user])

    @app.get("/api/invoices/<int:object_id>")
    def get_invoice(object_id: int):
        if current_user() is None:
            return jsonify(error="login required"), 401
        if object_id not in invoices:
            return jsonify(error="not found"), 404
        return jsonify(invoices[object_id])

    @app.patch("/api/invoices/<int:object_id>")
    def update_invoice(object_id: int):
        user = current_user()
        if user is None:
            return jsonify(error="login required"), 401
        invoice = invoices.get(object_id)
        if invoice is None or invoice["owner"] != user:
            return jsonify(error="not found"), 404
        invoice["memo"] = (request.get_json(silent=True) or {}).get("memo", invoice["memo"])
        return jsonify(invoice)

    return app

from __future__ import annotations

import secrets

from flask import Flask, abort, jsonify, request


def create_app(settings: dict) -> Flask:
    app = Flask(__name__)
    invoices = {item["id"]: item for item in settings["invoices"]}
    sessions: dict[str, str] = {}

    def current_user() -> str:
        user = sessions.get(request.headers.get("Authorization", "").removeprefix("Bearer "))
        if user is None:
            abort(401)
        return user

    def owned_invoice(object_id: int) -> dict:
        invoice = invoices.get(object_id)
        if invoice is None or invoice["owner"] != current_user():
            abort(404)
        return invoice

    @app.errorhandler(401)
    @app.errorhandler(404)
    def error(exc):
        return jsonify(error=exc.name.lower()), exc.code

    @app.post("/api/login")
    def login():
        body = request.get_json(silent=True) or {}
        if settings["users"].get(body.get("user")) != body.get("password"):
            return jsonify(error="bad credentials"), 401
        token = secrets.token_hex(16)
        sessions[token] = body["user"]
        return jsonify(token=token)

    @app.get("/api/invoices")
    def list_invoices():
        user = current_user()
        return jsonify([i for i in invoices.values() if i["owner"] == user])

    @app.get("/api/invoices/<int:object_id>")
    def get_invoice(object_id: int):
        return jsonify(owned_invoice(object_id))

    @app.patch("/api/invoices/<int:object_id>")
    def update_invoice(object_id: int):
        invoice = owned_invoice(object_id)
        invoice["memo"] = (request.get_json(silent=True) or {}).get("memo", invoice["memo"])
        return jsonify(invoice)

    return app
